plurals.en.ui.guidesCount:
(n: number) => {
      const mod10 = n % 10;
      const mod100 = n % 100;
      const word =
        mod10 === 1 && mod100 !== 11
          ? 'покликач'
          : mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)
            ? 'покликачі'
            : 'покликачів';
      return `${n} ${word}`;
    }

